#!/usr/bin/env node
/**
 * Tests for the resumable full-gate and merge-gate stalls of workflows/dev-loop.js: a red one resumes with
 * resumeFromRunId (never a fresh relaunch that redoes the finished blocks), the resumed run's gate and fix prompts carry
 * the resolution so they miss the cache and issue new calls, and the finished blocks' prompts stay identical so they
 * replay. stall.md describes it. Harness: tools/dev-loop.harness.mjs.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { run, ARGS, ARGS_M, review, impl, gate, laneGate } from './dev-loop.harness.mjs';

const VERIFY = 'node --test x';
const LITE = { ...ARGS, verify: VERIFY, targeted: 'node --test {files}', start: { head: 'abc1234', dirty: ['notes/todo.md'] } };
const GUIDE = 'revert the cache change and keep the lookup';
const RED = gate('red', { test: 'suite broke in lib' });
const green = () => impl({ gate: gate() });
const fullGates = (calls) => calls.filter((c) => /^full gate/.test(c.opts.label ?? '') && c.opts.agentType !== 'implementer');
const implementers = (calls) => calls.filter((c) => c.opts.agentType === 'implementer');
const prompts = (list) => new Set(list.map((c) => c.prompt));
const queue = (...lines) => ({ fullGate: () => ({ gate: lines.length > 1 ? lines.shift() : lines[0] }) });

const task = (id, files, dependsOn = []) => ({ id, title: `task-${id}-title`, files, dependsOn, tdd: false, criteria: [] });
const TWO_LANES = [task('T1', ['src/Orders/OrdersQuery.cs']), task('T2', ['src/Orders/OrdersQuery.cs'], ['T1']), task('T3', ['src/Orders/Dto/']), task('T4', ['src/Orders/Dto/Row.cs'])];
const LANES = { ...ARGS_M, verify: VERIFY, lanes: true, plan: { tasks: TWO_LANES } };
const lanesWith = (merge) => (prompt, opts) => {
  const n = /^lane (\d+) /.exec(opts.label)?.[1];
  return n ? { line: JSON.stringify({ lane: `l${n}`, path: `C:/lanes/l${n}`, branch: `deliver-lane/l${n}` }) } : { gate: merge() };
};
const STALL_MD = join(dirname(fileURLToPath(import.meta.url)), '..', 'skills', 'deliver', 'references', 'stall.md');

test('given a red full gate that stays red after its fix, when the run stalls, then the resume says to relaunch with resumeFromRunId and a round 0 resolution', async () => {
  // Given / When
  const { out } = await run(LITE, [review([])], [green(), green()], queue(RED));

  // Then
  assert.equal(out.stall.why, 'gate-red');
  assert.match(out.resume, /resumeFromRunId/);
  assert.doesNotMatch(out.resume, /WITHOUT resumeFromRunId/);
  assert.match(out.resume, /round: 0/);
});

test('given a red full gate stall resumed with guidance, when the loop runs again, then a new fix call carries the guidance and the finished block is not redone', async () => {
  // Given
  const first = await run(LITE, [review([])], [green(), green()], queue(RED));

  // When
  const again = await run({ ...LITE, resolutions: [{ round: 0, guidance: GUIDE }] }, [review([])], [green(), green()], queue(RED, gate()));

  // Then
  const fix = again.calls.find((c) => /^fix · full gate/.test(c.opts.label ?? ''));
  assert.match(fix.prompt, new RegExp(GUIDE));
  assert.ok(!prompts(first.calls.filter((c) => /^fix · full gate/.test(c.opts.label ?? ''))).has(fix.prompt));
  assert.equal(implementers(again.calls)[0].prompt, implementers(first.calls)[0].prompt);
});

test('given a red full gate stall resumed with a retry, when the loop runs again, then no full-gate prompt repeats the first run so none replays from the cache', async () => {
  // Given
  const first = await run(LITE, [review([])], [green(), green()], queue(RED));

  // When
  const again = await run({ ...LITE, resolutions: [{ round: 0, retry: true }] }, [review([])], [green(), green()], queue(RED, gate()));

  // Then
  const before = prompts(fullGates(first.calls));
  assert.ok(fullGates(again.calls).length >= 1);
  for (const c of fullGates(again.calls)) assert.ok(!before.has(c.prompt), c.opts.label);
});

test('given lanes whose merge gate is red, when the run stalls, then the resume says to relaunch with resumeFromRunId', async () => {
  // Given / When
  const { out } = await run(LANES, [review([]), review([]), review([])], [green(), green()], { lanes: lanesWith(() => laneGate('red', { test: 'merged tree broke' })) });

  // Then
  assert.equal(out.stall.why, 'gate-red');
  assert.match(out.resume, /resumeFromRunId/);
  assert.doesNotMatch(out.resume, /WITHOUT resumeFromRunId/);
});

test('given a merge gate stall resumed with a retry, when the loop runs again, then a new merge call is made and the lane implementers are not redone', async () => {
  // Given
  const first = await run(LANES, [review([]), review([]), review([])], [green(), green()], { lanes: lanesWith(() => laneGate('red', { test: 'merged tree broke' })) });

  // When
  const again = await run({ ...LANES, resolutions: [{ round: 0, retry: true }] }, [review([]), review([]), review([])], [green(), green()], { lanes: lanesWith(() => laneGate()) });

  // Then
  const merges = (calls) => calls.filter((c) => c.opts.label === 'lanes · merge');
  assert.equal(merges(again.calls).length, 1);
  assert.ok(!prompts(merges(first.calls)).has(merges(again.calls)[0].prompt));
  assert.deepEqual([...prompts(implementers(again.calls))].sort(), [...prompts(implementers(first.calls))].sort());
});

test('given stall.md, when its gate stall text is read, then it describes the resume of a full-gate or merge-gate stall that keeps the finished blocks', () => {
  // Given
  const lines = readFileSync(STALL_MD, 'utf8').split(/\r?\n/);

  // When / Then
  assert.ok(lines.some((l) => /full gate/i.test(l) && /merge gate/i.test(l) && /resumeFromRunId/.test(l) && /finished blocks/i.test(l)));
});
